use crate::*;
use vexel_xml::{TokenKind, XmlSpan, XmlToken};

pub(crate) const MAX_PATH_BYTES: usize = 64 * 1024;
pub(crate) const MAX_PATH_NUMBERS: usize = 4096;

pub(crate) fn span(source: &[u8], s: XmlSpan) -> Option<&[u8]> {
    s.slice(source)
}
pub(crate) fn eq(source: &[u8], s: XmlSpan, b: &[u8]) -> bool {
    span(source, s) == Some(b)
}
pub(crate) fn attr(source: &[u8], tokens: &[XmlToken], e: usize, name: &[u8]) -> Option<XmlSpan> {
    tokens.get(e)?;
    tokens
        .iter()
        .skip(e + 1)
        .take_while(|a| a.kind == TokenKind::Attribute)
        .find(|a| a.prefix.length == 0 && eq(source, a.local_name, name))
        .map(|a| a.value)
}
pub(crate) fn attr0(source: &[u8], tokens: &[XmlToken], e: usize, name: &[u8]) -> XmlSpan {
    attr(source, tokens, e, name).unwrap_or_default()
}
pub(crate) fn number(source: &[u8], s: XmlSpan) -> Option<f64> {
    let b = span(source, s)?;
    if b.is_empty() || b.len() >= 128 {
        return None;
    }
    let b = b.trim_ascii_start();
    let t = std::str::from_utf8(b).ok()?;
    let n = t.parse::<f64>().ok()?;
    n.is_finite().then_some(n)
}
pub(crate) fn time(source: &[u8], s: XmlSpan) -> Option<f64> {
    let b = span(source, s)?;
    if b.is_empty() || b.len() >= 128 {
        return None;
    }
    let (body, mul) = if b.ends_with(b"ms") {
        (&b[..b.len() - 2], 0.001)
    } else if b.ends_with(b"s") {
        (&b[..b.len() - 1], 1.0)
    } else {
        (b, 1.0)
    };
    let n = std::str::from_utf8(body.trim_ascii_start())
        .ok()?
        .parse::<f64>()
        .ok()?;
    let v = n * mul;
    if n.is_finite() && n >= 0.0 && v.is_finite() && v <= MAX_TIMELINE_SECONDS {
        Some(v)
    } else {
        None
    }
}
pub(crate) fn diagnostic(d: &mut Document<'_>, kind: DiagnosticKind, offset: usize) {
    if d.diagnostics.len() < MAX_DIAGNOSTICS {
        d.diagnostics.push(Diagnostic { kind, offset })
    }
}
pub(crate) fn element_span(tokens: &[XmlToken], i: usize) -> Option<XmlSpan> {
    let start = tokens.get(i)?.source.offset;
    let mut end = start.checked_add(tokens[i].source.length)?;
    if tokens[i].kind == TokenKind::StartElement {
        let depth = tokens[i].depth;
        let close = tokens
            .iter()
            .skip(i + 1)
            .find(|t| t.kind == TokenKind::EndElement && t.depth == depth)?;
        end = close.source.offset.checked_add(close.source.length)?;
    }
    Some(XmlSpan {
        offset: start,
        length: end.checked_sub(start)?,
    })
}
pub(crate) fn attr_kind(source: &[u8], s: XmlSpan) -> (Attribute, bool) {
    let b = span(source, s).unwrap_or_default();
    let a = match b {
        b"x" => Some(Attribute::X),
        b"y" => Some(Attribute::Y),
        b"width" => Some(Attribute::Width),
        b"height" => Some(Attribute::Height),
        b"cx" => Some(Attribute::Cx),
        b"cy" => Some(Attribute::Cy),
        b"r" => Some(Attribute::R),
        b"rx" => Some(Attribute::Rx),
        b"ry" => Some(Attribute::Ry),
        b"opacity" => Some(Attribute::Opacity),
        b"fill-opacity" => Some(Attribute::FillOpacity),
        b"stroke-opacity" => Some(Attribute::StrokeOpacity),
        b"fill" => Some(Attribute::Fill),
        b"stroke" => Some(Attribute::Stroke),
        b"stroke-width" => Some(Attribute::StrokeWidth),
        b"stroke-dashoffset" => Some(Attribute::StrokeDashoffset),
        b"d" => Some(Attribute::D),
        b"transform" => Some(Attribute::Transform),
        _ => None,
    };
    (a.unwrap_or(Attribute::Motion), b == b"transform")
}
pub(crate) fn color(source: &[u8], s: XmlSpan) -> Option<[u8; 4]> {
    let b = span(source, s)?;
    if b == b"none" {
        return Some([0; 4]);
    }
    if b.len() == 4 && b[0] == b'#' {
        let mut c = [0, 0, 0, 255];
        for i in 0..3 {
            c[i] = hex(b[i + 1])?.checked_mul(17)?
        }
        return Some(c);
    }
    if (b.len() == 7 || b.len() == 9) && b[0] == b'#' {
        let mut c = [0, 0, 0, 255];
        let n = if b.len() == 9 { 4 } else { 3 };
        for i in 0..n {
            c[i] = hex(b[1 + i * 2])?
                .checked_mul(16)?
                .checked_add(hex(b[2 + i * 2])?)?
        }
        return Some(c);
    }
    Some(match b {
        b"black" => [0, 0, 0, 255],
        b"white" => [255, 255, 255, 255],
        b"red" => [255, 0, 0, 255],
        b"green" => [0, 128, 0, 255],
        b"blue" => [0, 0, 255, 255],
        b"yellow" => [255, 255, 0, 255],
        b"cyan" => [0, 255, 255, 255],
        b"magenta" => [255, 0, 255, 255],
        b"gray" | b"grey" => [128, 128, 128, 255],
        b"transparent" => [0, 0, 0, 0],
        _ => return None,
    })
}
pub(crate) fn hex(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}
pub(crate) fn parse_value(
    source: &[u8],
    s: XmlSpan,
    a: Attribute,
    k: Kind,
    tt: TransformType,
) -> Option<Value> {
    let mut v = Value {
        raw: s,
        ..Value::default()
    };
    if k == Kind::Motion {
        v.kind = ValueKind::Motion;
        return Some(v);
    }
    if k == Kind::Transform {
        let b = span(source, s)?;
        if b.is_empty() || b.len() > 256 {
            return None;
        }
        let (vals, count) = number_list(b, 4)?;
        let (min, max) = match tt {
            TransformType::Rotate => (1, 3),
            TransformType::Translate | TransformType::Scale => (1, 2),
            _ => (1, 1),
        };
        if count < min || count > max {
            return None;
        }
        v.kind = ValueKind::Transform;
        v.number[..count].copy_from_slice(&vals[..count]);
        v.number[3] = count as f64;
        return Some(v);
    }
    if a == Attribute::D {
        v.kind = ValueKind::Path;
        return Some(v);
    }
    if matches!(a, Attribute::Fill | Attribute::Stroke) {
        v.kind = ValueKind::Color;
        v.rgba = color(source, s)?;
        return Some(v);
    }
    v.kind = ValueKind::Number;
    v.number[0] = number(source, s)?;
    Some(v)
}
