        }
        if !digits {
            return None;
        }
        if matches!(bytes.get(pos), Some(b'e' | b'E')) {
            pos += 1;
            if matches!(bytes.get(pos), Some(b'+' | b'-')) {
                pos += 1;
            }
            let exp = pos;
            while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
                pos += 1;
            }
            if exp == pos {
                return None;
            }
        }
        let value = std::str::from_utf8(&bytes[start..pos])
            .ok()?
            .parse::<f64>()
            .ok()?;
        if !value.is_finite() {
            return None;
        }
        values[count] = value;
        count += 1;
    }
    Some((values, count))
}
pub(crate) fn base_value(
    source: &[u8],
    tokens: &[XmlToken],
    target: usize,
    a: Attribute,
    k: Kind,
    tt: TransformType,
) -> Option<Value> {
    if k == Kind::Transform {
        let mut v = Value {
            kind: ValueKind::Transform,
            ..Value::default()
        };
        v.number[3] = match tt {
            TransformType::Scale => {
                v.number[0] = 1.;
                v.number[1] = 1.;
                2.
            }
            TransformType::Translate => 2.,
            _ => 1.,
        };
        return Some(v);
    }
    if k == Kind::Motion {
        return Some(Value {
            kind: ValueKind::Motion,
            ..Value::default()
        });
    }
    let Some(raw) = attr(source, tokens, target, a.name().as_bytes()) else {
        let mut v = Value::default();
        if matches!(a, Attribute::Fill | Attribute::Stroke) {
            v.kind = ValueKind::Color;
            if a == Attribute::Fill {
                v.rgba[3] = 255
            }
        } else if matches!(
            a,
            Attribute::Opacity | Attribute::FillOpacity | Attribute::StrokeOpacity
        ) {
            v.number[0] = 1.
        }
        return Some(v);
    };
    parse_value(source, raw, a, k, tt)
}
pub(crate) fn split(
    source: &[u8],
    s: XmlSpan,
    allocation_failed: &mut bool,
) -> Option<Vec<XmlSpan>> {
    let b = span(source, s)?;
    let count = b.iter().filter(|&&x| x == b';').count().checked_add(1)?;
    if count > MAX_VALUES {
        return None;
    }
    let mut out = Vec::new();
    if out.try_reserve_exact(count).is_err() {
        *allocation_failed = true;
        return None;
    }
    let mut start = 0;
    for i in 0..=b.len() {
        if i == b.len() || b[i] == b';' {
            let mut a = start;
            let mut z = i;
            while a < z && b" \t\r\n".contains(&b[a]) {
                a += 1
            }
            while z > a && b" \t\r\n".contains(&b[z - 1]) {
                z -= 1
            }
            if a == z || out.len() >= MAX_VALUES {
                return None;
            }
            out.push(XmlSpan {
                offset: s.offset.checked_add(a)?,
                length: z - a,
            });
            start = i.saturating_add(1)
        }
    }
    Some(out)
}
pub(crate) fn sync_time(src: &[u8], s: XmlSpan, t: &mut Track, is_begin: bool) -> bool {
    if eq(src, s, b"indefinite") {
        if is_begin {
            t.begin_indefinite = true
        } else {
            t.has_end = false
        }
        return true;
    }
    if let Some(v) = time(src, s) {
        if is_begin {
            t.begin_offset = v
        } else {
            t.end_seconds = v;
            t.has_end = true
        }
        return true;
    }
    let Some(b) = span(src, s) else { return false };
    let Some(dot) = b.iter().position(|&x| x == b'.') else {
        return false;
    };
    if dot == 0 || dot + 1 >= b.len() {
        return false;
    }
    let suffix_end = (dot + 1..b.len())
        .find(|&i| matches!(b[i], b'+' | b'-'))
        .unwrap_or(b.len());
    let suffix = &b[dot + 1..suffix_end];
    let sync_end = match suffix {
        b"end" => true,
        b"begin" => false,
        _ => return false,
    };
    let mut off = 0.;
    if suffix_end < b.len() {
        let n = XmlSpan {
            offset: s.offset + suffix_end + 1,
            length: b.len() - suffix_end - 1,
        };
        off = match time(src, n) {
            Some(n) => n,
            None => return false,
        };
        if b[suffix_end] == b'-' {
            off = -off
        }
    }
    let id = XmlSpan {
        offset: s.offset,
        length: dot,
    };
    if id.length == 0 {
        return false;
    }
    if is_begin {
        t.has_begin_sync = true;
        t.begin_sync_end = sync_end;
        t.begin_offset = off;
        t.begin_sync_id = Some(id)
    } else {
        t.has_end = true;
        t.end_is_sync = true;
        t.end_seconds = off;
        t.end_sync_id = Some(id)
    }
    true
}
pub(crate) fn path_shape(src: &[u8], s: XmlSpan) -> Option<([u8; 1024], usize, usize)> {
    let b = span(src, s)?;
    if b.is_empty() || b.len() > MAX_PATH_BYTES {
        return None;
    }
    let (mut commands, mut command_count, mut nums, mut i) = ([0; 1024], 0, 0, 0);
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_alphabetic() {
            if !b"MmLlHhVvCcSsQqTtAaZz".contains(&c) || command_count >= commands.len() {
                return None;
            }
            commands[command_count] = c;
            command_count += 1;
            i += 1;
            continue;
        }
        if b" \t\r\n,".contains(&c) {
            i += 1;
            continue;
        }
        let start = i;
        if matches!(c, b'+' | b'-') {
            i += 1
        }
        let mut digits = false;
        while b.get(i).is_some_and(u8::is_ascii_digit) {
            i += 1;
            digits = true
        }
        if b.get(i) == Some(&b'.') {
            i += 1;
            while b.get(i).is_some_and(u8::is_ascii_digit) {
                i += 1;
                digits = true
            }
        }
        if !digits {
            return None;
        }
        if matches!(b.get(i), Some(b'e' | b'E')) {
            i += 1;
            if matches!(b.get(i), Some(b'+' | b'-')) {
                i += 1
            }
            let exp = i;
            while b.get(i).is_some_and(u8::is_ascii_digit) {
                i += 1
            }
            if i == exp {
                return None;
            }
        }
        if i == start {
            return None;
        }
        nums += 1;
        if nums > MAX_PATH_NUMBERS {
            return None;
        }
    }
    if command_count == 0 {
        None
    } else {
        Some((commands, command_count, nums))
    }
}
pub(crate) fn paths_match(src: &[u8], a: XmlSpan, b: XmlSpan) -> bool {
    match (path_shape(src, a), path_shape(src, b)) {
        (Some((x, xc, n)), Some((y, yc, m))) => xc == yc && n == m && x[..xc] == y[..yc],
        _ => false,
    }
}

