fn parse_track(
    src: &[u8],
    tokens: &[XmlToken],
    i: usize,
    parent: usize,
    d: &mut Document<'_>,
    allocation_failed: &mut bool,
    meter: &mut Meter<'_>,
) -> Option<Track> {
    if !meter.checkpoint() {
        return None;
    }
    let tag = &tokens[i];
    let name = span(src, tag.local_name)?;
    let mut t = Track::default();
    t.id = attr0(src, tokens, i, b"id");
    t.target = element_span(tokens, parent)?;
    t.element = element_span(tokens, i)?;
    if tag.prefix.length != 0 {
        diagnostic(d, DiagnosticKind::UnsupportedElement, tag.name.offset);
        return None;
    }
    t.kind = match name {
        b"animate" => Kind::Animate,
        b"animateTransform" => Kind::Transform,
        b"set" => Kind::Set,
        b"animateMotion" => Kind::Motion,
        _ => {
            diagnostic(d, DiagnosticKind::UnsupportedElement, tag.name.offset);
            return None;
        }
    };
    let an = attr0(src, tokens, i, b"attributeName");
    if t.kind == Kind::Motion {
        t.attribute = Attribute::Motion
    } else {
        if an.length == 0 {
            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
            return None;
        }
        let (a, tr) = attr_kind(src, an);
        t.attribute = a;
        if t.kind == Kind::Transform {
            if !tr {
                diagnostic(d, DiagnosticKind::UnsupportedAttribute, an.offset);
                return None;
            }
        } else if tr || a == Attribute::Motion {
            diagnostic(d, DiagnosticKind::UnsupportedAttribute, an.offset);
            return None;
        }
    }
    let ttspan = attr0(src, tokens, i, b"type");
    if t.kind == Kind::Transform {
        if ttspan.length == 0 || ttspan.length >= 16 {
            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
            return None;
        }
        let b = span(src, ttspan)?;
        t.transform_type = match b {
            b"translate" => TransformType::Translate,
            b"scale" => TransformType::Scale,
            b"rotate" => TransformType::Rotate,
            b"skewX" => TransformType::SkewX,
            b"skewY" => TransformType::SkewY,
            _ => {
                diagnostic(d, DiagnosticKind::UnsupportedAttribute, ttspan.offset);
                return None;
            }
        }
    }
    let at = attr0(src, tokens, i, b"attributeType");
    if at.length > 0 && !eq(src, at, b"XML") {
        diagnostic(d, DiagnosticKind::UnsupportedAttribute, at.offset);
        return None;
    }
    let cm = attr0(src, tokens, i, b"calcMode");
    t.calc_mode = match if cm.length == 0 {
        b"linear".as_slice()
    } else {
        span(src, cm)?
    } {
        b"linear" => CalcMode::Linear,
        b"discrete" => CalcMode::Discrete,
        b"spline" => CalcMode::Spline,
        b"paced" => CalcMode::Paced,
        _ => {
            diagnostic(d, DiagnosticKind::UnsupportedAttribute, cm.offset);
            return None;
        }
    };
    let fill = attr0(src, tokens, i, b"fill");
    t.fill_mode = match if fill.length == 0 {
        b"remove".as_slice()
    } else {
        span(src, fill)?
    } {
        b"remove" => FillMode::Remove,
        b"freeze" => FillMode::Freeze,
        _ => {
            diagnostic(d, DiagnosticKind::UnsupportedAttribute, fill.offset);
            return None;
        }
    };
    let add = attr0(src, tokens, i, b"additive");
    if add.length > 0 && !eq(src, add, b"replace") {
        if eq(src, add, b"sum") {
            t.additive_sum = true
        } else {
            diagnostic(d, DiagnosticKind::UnsupportedComposition, add.offset);
            return None;
        }
    }
    let acc = attr0(src, tokens, i, b"accumulate");
    if acc.length > 0 && !eq(src, acc, b"none") {
        if eq(src, acc, b"sum") {
            t.accumulate = true
        } else {
            diagnostic(d, DiagnosticKind::UnsupportedComposition, acc.offset);
            return None;
        }
    }
    if (t.kind == Kind::Motion && (t.additive_sum || t.accumulate))
        || (t.kind == Kind::Transform && t.accumulate)
        || (t.attribute == Attribute::D && (t.additive_sum || t.accumulate))
    {
        diagnostic(d, DiagnosticKind::UnsupportedComposition, tag.name.offset);
        return None;
    }
    let begin = attr0(src, tokens, i, b"begin");
    if begin.length > 0 && !sync_time(src, begin, &mut t, true) {
        diagnostic(d, DiagnosticKind::UnsupportedTiming, begin.offset);
        return None;
    }
    let end = attr0(src, tokens, i, b"end");
    if end.length > 0 && !sync_time(src, end, &mut t, false) {
        diagnostic(d, DiagnosticKind::UnsupportedTiming, end.offset);
        return None;
    }
    let dur = attr0(src, tokens, i, b"dur");
    if dur.length == 0 && t.kind != Kind::Set {
        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
        return None;
    }
    if eq(src, dur, b"indefinite") {
        t.duration_indefinite = true
    } else if dur.length > 0 {
        t.duration_seconds = match time(src, dur) {
            Some(n) => n,
            None => {
                diagnostic(d, DiagnosticKind::UnsupportedTiming, dur.offset);
                return None;
            }
        }
    }
    if !t.duration_indefinite && t.kind != Kind::Set && t.duration_seconds <= 0. {
        diagnostic(d, DiagnosticKind::InvalidTrack, dur.offset);
        return None;
    }
    if t.kind == Kind::Set && dur.length == 0 {
        t.duration_indefinite = true
    }
    let rep = attr0(src, tokens, i, b"repeatCount");
    if eq(src, rep, b"indefinite") {
        t.repeat_indefinite = true;
        t.repeat_count = f64::INFINITY
    } else if rep.length > 0 {
        t.repeat_count = match number(src, rep) {
            Some(n) if n > 0. && n <= 100000. => n,
            _ => {
                diagnostic(d, DiagnosticKind::UnsupportedTiming, tag.name.offset);
                return None;
            }
        }
    }
    if t.kind == Kind::Set {
        t.repeat_count = 1.
    }
    let rd = attr0(src, tokens, i, b"repeatDur");
    if eq(src, rd, b"indefinite") {
        t.repeat_duration_indefinite = true
    } else if rd.length > 0 {
        t.repeat_duration = match time(src, rd) {
            Some(n) => n,
            None => {
                diagnostic(d, DiagnosticKind::UnsupportedTiming, rd.offset);
                return None;
            }
        }
    }
    t.base_value = match base_value(src, tokens, parent, t.attribute, t.kind, t.transform_type) {
        Some(value) => value,
        None => {
            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
            return None;
        }
    };
    let vals = attr0(src, tokens, i, b"values");
    let from = attr0(src, tokens, i, b"from");
    let to = attr0(src, tokens, i, b"to");
    let by = attr0(src, tokens, i, b"by");
    if vals.length > 0 && (from.length > 0 || to.length > 0 || by.length > 0) {
        diagnostic(d, DiagnosticKind::InvalidTrack, vals.offset);
        return None;
    }
    let mut pieces = Vec::new();
    // Attribute lookup scans the contiguous XML attribute run repeatedly.
    // Charge its actual token span before examining the track's attributes.
    let attribute_count = tokens
        .iter()
        .skip(i + 1)
        .take_while(|a| a.kind == TokenKind::Attribute)
        .count();
    if !meter.charge(WorkKind::TokenVisit, attribute_count.saturating_mul(24)) {
        return None;
    }
    let attribute_bytes = tokens
        .iter()
        .skip(i + 1)
        .take_while(|a| a.kind == TokenKind::Attribute)
        .fold(0usize, |sum, a| {
            sum.saturating_add(a.name.length)
                .saturating_add(a.local_name.length)
                .saturating_add(a.value.length)
        });
    if !meter.charge(WorkKind::SourceRead, attribute_bytes) {
        return None;
    }
    if pieces.try_reserve_exact(MAX_VALUES).is_err() {
        *allocation_failed = true;
        return None;
    }
    let mut implicit = false;
    let mut by_value = false;
    if t.kind == Kind::Motion {
        if !meter.charge(WorkKind::ReferenceProbe, tokens.len().saturating_sub(i)) {
            return None;
        }
        let path = resolve_motion_path(src, tokens, i)
            .filter(|p| parse_motion(src, *p, &mut t, allocation_failed, meter));
        if path.is_none() {
            diagnostic(d, DiagnosticKind::UnsupportedPath, tag.name.offset);
            return None;
        }
        let rot = attr0(src, tokens, i, b"rotate");
        if eq(src, rot, b"auto") {
            t.motion_rotate_auto = true
        } else if eq(src, rot, b"auto-reverse") {
            t.motion_rotate_auto = true;
            t.motion_rotate_reverse = true
        } else if rot.length > 0 {
            t.motion_fixed_rotation = match number(src, rot) {
                Some(n) => n,
                _ => {
                    diagnostic(d, DiagnosticKind::UnsupportedAttribute, rot.offset);
                    return None;
                }
            }
        }
        pieces.push(path.unwrap());
    } else if vals.length > 0 {
        pieces = match split(src, vals, allocation_failed) {
            Some(p) => p,
            None => {
                diagnostic(d, DiagnosticKind::InvalidTrack, vals.offset);
                return None;
            }
        }
    } else if t.kind == Kind::Set {
        if to.length == 0 {
            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
            return None;
        }
        pieces.push(to)
    } else if from.length > 0 && to.length > 0 {
        pieces.extend([from, to])
    } else if to.length > 0 {
        implicit = true;
        pieces.push(to)
    } else if by.length > 0 {
