pub(crate) fn split(
    source: &[u8],
    s: XmlSpan,
    allocation_failed: &mut bool,
    meter: &mut Meter<'_>,
) -> Option<Vec<XmlSpan>> {
    let b = span(source, s)?;
    let mut separators = 0usize;
    for &byte in b {
        if !meter.charge(WorkKind::SourceRead, 1) {
            return None;
        }
        if byte == b';' {
            separators = separators.checked_add(1)?;
        }
    }
    let count = separators.checked_add(1)?;
    if count > MAX_VALUES {
        return None;
    }
    let mut out = Vec::new();
    if out.try_reserve_exact(count).is_err() {
        *allocation_failed = true;
        return None;
    }
    let mut start = 0;
    for i in 0..=b.len() {
        if !meter.charge(WorkKind::SourceRead, 1) {
            return None;
        }
        if i == b.len() || b[i] == b';' {
            let mut a = start;
            let mut z = i;
            while a < z && b" \t\r\n".contains(&b[a]) {
                if !meter.charge(WorkKind::SourceRead, 1) {
                    return None;
                }
                a += 1
            }
            while z > a && b" \t\r\n".contains(&b[z - 1]) {
                if !meter.charge(WorkKind::SourceRead, 1) {
                    return None;
                }
                z -= 1
            }
            if a == z || out.len() >= MAX_VALUES {
                return None;
            }
            out.push(XmlSpan {
                offset: s.offset.checked_add(a)?,
                length: z - a,
            });
            start = i.saturating_add(1)
        }
    }
    Some(out)
}
